8	/**
9	 * Consolidated duplicate detection for create-owner: rejects a request whose whole derived
10	 * {@code identityKey} equals that of an existing owner, responding 409 via
11	 * {@link DuplicateIdentityException}.
12	 *
13	 * <p>The key (see {@link Owner#getIdentityKey()}) is
14	 * {@code normalizedTelephone|email|householdId}, so the former separate telephone, email and
15	 * household checks are now a single full-key comparison. Because the telephone is part of the
16	 * key, two members of the same household (same {@code householdId}) with different telephones
17	 * have different identity keys and are both allowed; only an exact full-key match is a duplicate.
18	 *
19	 * <p>Runs after {@link AssignHousehold} (so the built owner already carries its
20	 * {@code householdId}, if any) and before {@link SaveOwner} persists anything. The new owner
21	 * is not yet in the repository, so it is never compared against itself.
22	 */
23	public class EnsureUniqueIdentity {
24	
25	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
26	            throws DuplicateIdentityException {
27	        String identityKey = owner.getIdentityKey();
28	        for (Owner existing : ownerRepository.findAll()) {
29	            if (identityKey.equals(existing.getIdentityKey())) {
30	                throw new DuplicateIdentityException(identityKey);
31	            }
32	        }
33	    }
34	}
